// Yesterday 00:00 -> 00:00 in the store's operating timezone, not UTC days.
// A Gulf store's yesterday ends at 20:00 UTC; an order at 21:00 UTC belongs to
// the next business day, not to this digest.
const zone = 'Asia/Dubai';
const todayStart = $now.setZone(zone).startOf('day');
return [{ json: {
  p_start: todayStart.minus({ days: 1 }).toISO(),
  p_end: todayStart.toISO(),
  zone: zone
} }];

const resp = $input.first().json;
const httpCode = (resp && resp.statusCode) ? resp.statusCode : 0;
const raw = (resp && resp.body !== undefined) ? resp.body : resp;
const s = Array.isArray(raw) ? (raw[0] || {}) : (raw || {});
const ok = httpCode === 200 && s && s.window_start;

// Money formatting per arabic-style-guide 3.1 (Hussein, 2026-08-04): Western
// digits, thousands separators, currency code AFTER the number, no pointless
// decimals. Same rule the customer-facing messages use, so the owner's digest
// and the customer's message quote figures the same way.
const ZERO_DECIMAL = ['LBP','IQD','JPY','KRW','VND','CLP','ISK'];
function fmtMoney(amount, cur) {
  const c = String(cur || '').toUpperCase();
  const n = Number(amount);
  if (!isFinite(n)) return String(amount) + ' ' + c;
  const dp = (ZERO_DECIMAL.indexOf(c) >= 0 || Math.abs(n - Math.round(n)) <= 0.004) ? 0 : 2;
  return n.toLocaleString('en-US', { minimumFractionDigits: dp, maximumFractionDigits: dp }) + ' ' + c;
}
// NEVER summed across currencies: a Lebanese order is booked in AED while the
// customer paid in LBP, so one total would be a fiction.
function money(map) {
  const ks = Object.keys(map || {});
  if (!ks.length) return 'none';
  return ks.map(k => fmtMoney(map[k], k)).join('   ');
}
function byNum(map) {
  const ks = Object.keys(map || {}).sort();
  if (!ks.length) return 'none';
  return ks.map(k => 'touch ' + k + ': ' + map[k]).join('   ');
}

// Label the day from the LOCAL window we asked for, not from the RPC's echo.
// Postgres normalises the timestamptz to UTC on the way back, so a Dubai day
// starting 2026-08-03T00:00+04:00 returns as 2026-08-02T20:00+00:00 and slicing
// that gives the wrong date - the digest for the 3rd would be headed 'the 2nd'.
const win = $('Compute Window').first().json;
const day = win && win.p_start ? String(win.p_start).slice(0, 10) : '(unknown day)';

if (!ok) {
  const text = 'Cart recovery digest ' + day + ' UNAVAILABLE - digest query failed (HTTP ' + httpCode + ')';
  return [{ json: { ok: false, stats: {}, slack_body: { channel: '#automation-errors', text: text,
    blocks: [{ type: 'section', text: { type: 'mrkdwn', text: '*' + text + '*\nThe recovery system may be running fine - this is the reporting layer failing. Check run_logs directly.' } }] } } }];
}

const rate = (s.recovery_rate_pct === null || s.recovery_rate_pct === undefined)
  ? 'no attempts closed'
  : (s.recovery_rate_pct + '%  (' + s.recovered_orders + ' of ' + s.recovery_attempts_closed + ' closed attempts)');

const blocks = [
  { type: 'header', text: { type: 'plain_text', text: 'Cart recovery digest - ' + day, emoji: false } },
  { type: 'section', fields: [
    { type: 'mrkdwn', text: '*Recovered orders:*\n' + (s.recovered_orders || 0) },
    { type: 'mrkdwn', text: '*Recovered revenue:*\n' + money(s.recovered_revenue) },
    { type: 'mrkdwn', text: '*Recovery rate:*\n' + rate },
    { type: 'mrkdwn', text: '*Carts tracked:*\n' + (s.carts_created || 0) }
  ]},
  { type: 'section', text: { type: 'mrkdwn', text: '*Bought before any message:* ' + (s.converted_before_first_touch || 0) + '  (' + money(s.pre_touch_revenue) + ') - _not counted as recovery_' } },
  { type: 'section', fields: [
    { type: 'mrkdwn', text: '*Touches sent:*\n' + (s.touches_total || 0) + '  (' + byNum(s.touches_by_number) + ')' },
    { type: 'mrkdwn', text: '*Replies / opt-outs:*\n' + (s.replies_received || 0) + ' in, ' + (s.replies_handled || 0) + ' handled, ' + (s.opt_outs || 0) + ' opt-outs' },
    { type: 'mrkdwn', text: '*Sequences exhausted:*\n' + (s.exhausted || 0) },
    { type: 'mrkdwn', text: '*Auto-replies sent:*\n' + (s.auto_replies_sent || 0) }
  ]},
  { type: 'section', fields: [
    { type: 'mrkdwn', text: '*Deferred (window/prayer/age):*\n' + (s.deferrals || 0) },
    { type: 'mrkdwn', text: '*Skipped (Shopify unknown):*\n' + (s.skipped_api_failure || 0) },
    { type: 'mrkdwn', text: '*Send failures:*\n' + (s.send_failures || 0) },
    { type: 'mrkdwn', text: '*Sweeps / degraded:*\n' + (s.sweeps_logged || 0) + ' / ' + (s.sweeps_degraded || 0) }
  ]},
  { type: 'context', elements: [{ type: 'mrkdwn', text: 'Intake: ' + (s.carts_created || 0) + ' created, ' + (s.cart_updates || 0) + ' cart edits, ' + (s.no_phone_skips || 0) + ' skipped with no phone, ' + (s.hmac_failures || 0) + ' HMAC rejections, ' + (s.duplicate_inbound || 0) + ' duplicate inbound dropped  |  runs ' + (s.runs_total || 0) + ' (' + (s.runs_partial || 0) + ' partial, ' + (s.runs_failed || 0) + ' failed)' }] }
];

const errs = Array.isArray(s.errors) ? s.errors : [];
if (errs.length) {
  blocks.push({ type: 'section', text: { type: 'mrkdwn', text: '*Failures:*\n' + errs.slice(0, 5)
    .map(e => '- ' + (e.workflow || '?') + ' / ' + (e.step || '?') + ' - ' + String(e.error || '').slice(0, 120)).join('\n') } });
} else {
  blocks.push({ type: 'context', elements: [{ type: 'mrkdwn', text: 'No failed runs in the window.' }] });
}

const text = 'Cart recovery digest ' + day + ': ' + (s.recovered_orders || 0) + ' recovered (' + money(s.recovered_revenue) + '), ' + (s.touches_total || 0) + ' touches, ' + (s.runs_failed || 0) + ' failures';
return [{ json: { ok: true, stats: s, slack_body: { channel: '#leads', text: text, blocks: blocks } } }];
